"""Area-of-interest snapshots for one human. JSON-friendly dicts; no protocol bytes.

A gateway adapter turns these dicts into whatever wire format it speaks. Field names here are
this project's own, not original Rules of Survival fields. Radii are development values.
"""

import math

from solo_engine import combat, items, lifecycle, loot, results, spatial, zone
from solo_engine.geometry import SpatialGrid
from solo_engine.model import (
    LifeState,
    MatchEvent,
    MatchPhase,
    Participant,
    SoloMatch,
    WeaponSlot,
)

AOI_RADIUS = 250.0  # metres: other participants, vehicles and local events
NEAR_RADIUS = 60.0  # metres: loot and doors
RECENT_ELIMINATION_SECONDS = 5.0  # eliminated participants stay visible this long
HEALTH_BUCKETS = 10  # others' health is shown in tenths, never exact

# Events every participant in the match receives, wherever they happen.
GLOBAL_EVENTS = frozenset(
    {
        "match_created",
        "phase",
        "aircraft",
        "cancelled",
        "zone_announce",
        "zone_shrink_start",
        "zone_final",
        "elimination",
        "match_end",
    }
)
# Keys whose value is a participant id that locates (and may concern) the event.
_PARTICIPANT_KEYS = ("participant_id", "victim_id", "shooter_id", "attacker_id", "killer_id")


def _r(value: float, places: int = 2) -> float:
    return round(float(value), places)


def _within(ax: float, ay: float, bx: float, by: float, radius: float) -> bool:
    dx, dy = ax - bx, ay - by
    return dx * dx + dy * dy <= radius * radius


def _weapon_view(slot: WeaponSlot | None) -> dict | None:
    if slot is None:
        return None
    return {
        "weapon_id": slot.weapon_id,
        "mag": slot.mag,
        "mag_capacity": items.mag_capacity(slot),
        "attachments": dict(slot.attachments),
    }


def self_view(match: SoloMatch, p: Participant) -> dict:
    inv = p.inventory
    stats = p.stats
    return {
        "id": p.participant_id,
        "name": p.display_name,
        "x": _r(p.x),
        "y": _r(p.y),
        "z": _r(p.z),
        "yaw": _r(p.yaw, 3),
        "life": p.life.value,
        "alive": p.alive,
        "stance": p.stance.value,
        "sprinting": p.sprinting,
        "swimming": p.swimming,
        "health": _r(p.health),
        "max_health": p.max_health,
        "boost": _r(combat.boost_of(match, p)),
        "armor": {"item_id": inv.armor_id, "durability": _r(inv.armor_durability)} if inv.armor_id else None,
        "helmet": {"item_id": inv.helmet_id, "durability": _r(inv.helmet_durability)} if inv.helmet_id else None,
        "backpack_id": inv.backpack_id,
        "backpack": dict(inv.backpack),
        "backpack_capacity": _r(loot.backpack_capacity(p)),
        "backpack_used": _r(loot.backpack_used(p)),
        "weapons": [_weapon_view(slot) for slot in inv.weapons],
        "active_slot": inv.active_slot,
        "reload_left": _r(p.reload_left),
        "healing_item": p.healing_item,
        "heal_left": _r(p.heal_left),
        "vehicle_id": p.vehicle_id,
        "stats": {
            "kills": stats.kills,
            "damage_dealt": _r(stats.damage_dealt),
            "damage_taken": _r(stats.damage_taken),
            "shots_fired": stats.shots_fired,
            "shots_hit": stats.shots_hit,
            "heals_used": stats.heals_used,
            "distance_travelled": _r(stats.distance_travelled, 1),
        },
        "placement": p.placement,
        "eliminated_by": p.eliminated_by,
    }


def health_bucket(health: float, max_health: float) -> int:
    """Health in tenths (0..10), rounded up: what a participant may know of someone else."""
    fraction = health / max_health if max_health > 0 else 0.0
    return max(0, min(HEALTH_BUCKETS, math.ceil(fraction * HEALTH_BUCKETS)))


def other_view(p: Participant) -> dict:
    return {
        "id": p.participant_id,
        "name": p.display_name,
        "bot": p.is_bot,  # development debug flag only
        "x": _r(p.x),
        "y": _r(p.y),
        "z": _r(p.z),
        "yaw": _r(p.yaw, 3),
        "life": p.life.value,
        "stance": p.stance.value,
        "vehicle_id": p.vehicle_id,
        "health_bucket": health_bucket(p.health, p.max_health),
    }


def _others(match: SoloMatch, human: Participant, grid: SpatialGrid) -> list[dict]:
    hx, hy = human.x, human.y
    seen: list[dict] = []
    for participant_id in sorted(grid.near(hx, hy, AOI_RADIUS)):
        p = match.participants.get(participant_id)
        if p is None or p is human or not p.alive:
            continue
        if _within(p.x, p.y, hx, hy, AOI_RADIUS):
            seen.append(other_view(p))
    # Recently eliminated participants are not in the grid; there are only a few of them.
    for participant_id in reversed(match.elimination_order):
        p = match.participants.get(participant_id)
        if p is None or p is human or p.eliminated_at is None:
            continue
        if match.clock - p.eliminated_at > RECENT_ELIMINATION_SECONDS:
            break
        if _within(p.x, p.y, hx, hy, AOI_RADIUS):
            seen.append(other_view(p))
    return seen


def _zone_view(match: SoloMatch, human: Participant) -> dict:
    z = match.zone
    if z.state == "inactive":
        return {"state": "inactive"}
    pending = z.state in ("waiting", "shrinking")
    until = zone.seconds_until_shrink(match)
    return {
        "state": z.state,
        "phase": z.phase_index,
        "current": {"x": _r(z.center_x), "y": _r(z.center_y), "radius": _r(z.radius)},
        "next": {"x": _r(z.next_x), "y": _r(z.next_y), "radius": _r(z.next_radius)} if pending else None,
        "seconds_until_shrink": _r(until) if math.isfinite(until) else None,
        "dps": z.dps,
        "outside": zone.outside(match, human.x, human.y),
    }


def _event_point(match: SoloMatch, event: MatchEvent) -> tuple[float, float] | None:
    data = event.data
    x, y = data.get("x"), data.get("y")
    if isinstance(x, (int, float)) and isinstance(y, (int, float)):
        return float(x), float(y)
    for key in _PARTICIPANT_KEYS:
        p = match.participants.get(data.get(key) or "")
        if p is not None:
            return p.x, p.y
    vehicle = match.vehicles.get(data.get("vehicle_id") or "")
    if vehicle is not None:
        return vehicle.x, vehicle.y
    door = match.doors.get(data.get("door_id") or "")
    if door is not None:
        return door.x, door.y
    return None


def event_relevant(match: SoloMatch, event: MatchEvent, human: Participant) -> bool:
    """Global events always; events about the human always; others only inside the AOI."""
    if event.kind in GLOBAL_EVENTS:
        return True
    data = event.data
    if any(data.get(key) == human.participant_id for key in _PARTICIPANT_KEYS):
        return True
    point = _event_point(match, event)
    return point is not None and _within(point[0], point[1], human.x, human.y, AOI_RADIUS)


_HEALTH_SUBJECT_KEYS = ("victim_id", "participant_id")  # whose health a damage/heal event carries


def _event_view(match: SoloMatch, event: MatchEvent, viewer: Participant) -> dict:
    """One event for one viewer. Someone else's exact health becomes `health_bucket` (0..10)."""
    view = {key: list(value) if isinstance(value, tuple) else value for key, value in event.data.items()}
    if "health" in view:
        subject_id = next((view[k] for k in _HEALTH_SUBJECT_KEYS if view.get(k)), None)
        if subject_id != viewer.participant_id:
            health = view.pop("health")
            subject = match.participants.get(subject_id or "")
            max_health = subject.max_health if subject is not None else match.config.max_health
            value = float(health) if isinstance(health, (int, float)) else 0.0
            view["health_bucket"] = health_bucket(value, max_health)
    view["kind"] = event.kind
    view["at"] = _r(event.at, 3)
    return view


def player_view(match: SoloMatch, human: Participant, grid: SpatialGrid, since: int = 0) -> dict:
    """Everything one human may see this tick. `since` skips events already delivered."""
    hx, hy = human.x, human.y
    phase = lifecycle.phase_view(match)
    aircraft = phase.pop("aircraft", None)
    view: dict = {
        "match_id": match.match_id,
        "tick": match.tick,
        "clock": _r(match.clock, 3),
        "phase": phase,
        "self": self_view(match, human),
        "others": _others(match, human, grid),
        "loot": [
            {"id": g.loot_id, "item_id": g.item_id, "quantity": g.quantity, "x": _r(g.x), "y": _r(g.y),
             "crate_id": g.crate_id}
            for g in spatial.loot_index(match).near(match, hx, hy, NEAR_RADIUS)
        ],  # fmt: skip; radius query on the shared per-match loot index, ordered by loot id
        "vehicles": [
            {"id": v.vehicle_id, "kind": v.kind, "x": _r(v.x), "y": _r(v.y), "yaw": _r(v.yaw, 3),
             "health": _r(v.health), "fuel": _r(v.fuel), "driver_id": v.driver_id,
             "passenger_ids": list(v.passenger_ids), "seats": v.seats}
            for v in match.vehicles.values()
            if _within(v.x, v.y, hx, hy, AOI_RADIUS)
        ],  # fmt: skip
        "doors": [
            {"id": d.door_id, "x": _r(d.x), "y": _r(d.y), "open": d.open}
            for d in match.doors.values()
            if _within(d.x, d.y, hx, hy, NEAR_RADIUS)
        ],
        "zone": _zone_view(match, human),
        "aircraft": aircraft if match.phase == MatchPhase.AIRCRAFT else None,
        "events": [_event_view(match, e, human) for e in match.events[since:] if event_relevant(match, e, human)],
        "results": None,
    }
    if match.phase in (MatchPhase.ENDED, MatchPhase.CLOSED) and match.results is not None:
        view["results"] = [results.result_view(r) for r in match.results]
    if human.life == LifeState.ELIMINATED:
        view["spectating"] = True
    return view
